const body = $json.body ?? $json;
const required = ['event', 'event_id', 'client_id', 'environment', 'occurred_at', 'schema_version'];
const errors = required.filter((key) => body[key] === undefined || body[key] === null || body[key] === '');
if (body.event !== 'onboarding.client_created') errors.push('event must be onboarding.client_created');
if (body.environment !== 'demo') errors.push('environment must be demo');
if (body.schema_version !== 1) errors.push('schema_version must be 1');
for (const key of ['event_id', 'client_id']) { if (body[key] && !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(body[key]))) errors.push(key + ' must be a UUID'); }
const forbidden = ['email', 'password', 'token', 'access_token', 'service_role'];
if (forbidden.some((key) => Object.hasOwn(body, key))) errors.push('payload contains a forbidden personal or secret field');
return [{ json: { accepted: errors.length === 0, event_id: body.event_id ?? null, correlation_id: body.event_id ?? null, errors } }];
